INSERT INTO `wp_posts` VALUES (12,0,'2026-01-23 13:53:59','2026-01-23 12:53:59','\n<!-- wp:cover {\"url\":\"https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?ixlib=rb-4.0.3u0026auto=formatu0026fit=cropu0026w=1920u0026q=80\",\"dimRatio\":50,\"overlayColor\":\"black\",\"isUserOverlayColor\":true,\"minHeight\":600,\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:600px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-backward-gradient has-background-dim\"></span><img class=\"wp-block-cover__image-background\" alt=\"\" src=\"https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?ixlib=rb-4.0.3u0026auto=formatu0026fit=cropu0026w=1920u0026q=80\" data-object-fit=\"cover\" /><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"4rem\",\"fontWeight\":\"800\"}}} -->\n<h1 class=\"has-text-align-center\" style=\"font-size:4rem;font-weight:800\">Alquiler vacacional en Dénia</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textAlign\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1.5rem\"}}} -->\n<p class=\"has-text-align-center\" style=\"font-size:1.5rem\">Descubre villas exclusivas para unas vacaciones inolvidables en la Costa Blanca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"primary\",\"style\":{\"border\":{\"radius\":\"50px\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-primary-background-color has-background wp-element-button\" href=\"/alojamientos\" style=\"border-radius:50px\">Ver Alojamientos</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer {\"height\":\"80px\"} -->\n<div style=\"height:80px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"has-text-align-center\">Alojamientos Destacados</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textAlign\":\"center\"} -->\n<p class=\"has-text-align-center\">Nuestra selección de propiedades premium con todas las comodidades.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:query {\"queryId\":0,\"query\":{\"perPage\":3,\"pages\":0,\"offset\":0,\"postType\":\"product\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"\",\"inherit\":false},\"displayLayout\":{\"type\":\"flex\",\"columns\":3},\"align\":\"wide\"} -->\n<div class=\"wp-block-query alignwide\"><!-- wp:post-template -->\n<!-- wp:post-featured-image {\"isLink\":true} /-->\n<!-- wp:post-title {\"isLink\":true,\"textAlign\":\"center\"} /-->\n<!-- wp:woocommerce/product-price {\"textAlign\":\"center\"} /-->\n<!-- wp:woocommerce/product-button {\"textAlign\":\"center\"} /-->\n<!-- /wp:post-template --></div>\n<!-- /wp:query --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"80px\"} -->\n<div style=\"height:80px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"secondary\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-secondary-background-color has-background\" style=\"padding-top:80px;padding-bottom:80px\"><!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"align\":\"center\",\"width\":64,\"height\":64,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter is-resized\"><img src=\"https://s.w.org/images/core/emoji/14.0.0/72x72/1f6e1.png\" alt=\"🛡️\" width=\"64\" height=\"64\" /></figure>\n<!-- /wp:image -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"has-text-align-center\">100% Seguro</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"textAlign\":\"center\"} -->\n<p class=\"has-text-align-center\">Reservas garantizadas y sistemas de pago cifrados de nivel bancario.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"align\":\"center\",\"width\":64,\"height\":64,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter is-resized\"><img src=\"https://s.w.org/images/core/emoji/14.0.0/72x72/1f4b3.png\" alt=\"💳\" width=\"64\" height=\"64\" /></figure>\n<!-- /wp:image -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"has-text-align-center\">Pago Flexible</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"textAlign\":\"center\"} -->\n<p class=\"has-text-align-center\">Paga el 40% ahora y el resto justo antes de tu llegada.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"align\":\"center\",\"width\":64,\"height\":64,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter is-resized\"><img src=\"https://s.w.org/images/core/emoji/14.0.0/72x72/23f3.png\" alt=\"⏳\" width=\"64\" height=\"64\" /></figure>\n<!-- /wp:image -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"has-text-align-center\">Gestión 24/7</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"textAlign\":\"center\"} -->\n<p class=\"has-text-align-center\">Atención personalizada y soporte a huéspedes durante toda la estancia.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"80px\"} -->\n<div style=\"height:80px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"has-text-align-center\">¿Eres propietario?</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"textAlign\":\"center\"} -->\n<p class=\"has-text-align-center\">Gestionamos tu propiedad en Dénia con la máxima rentabilidad y cuidado.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-outline\",\"style\":{\"border\":{\"radius\":\"50px\"}}} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" style=\"border-radius:50px\">Más información para Propietarios</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n','Inicio','','publish','closed','closed','','inicio','','','2026-01-23 14:25:34','2026-01-23 13:25:34','',0,'http://alquipressjaime.local/inicio/',0,'page','',0);
