INSERT INTO `wp_posts` VALUES (3526,0,'2026-01-23 15:01:23','2026-01-23 14:01:23','\n<!-- wp:cover {\"url\":\"https://images.unsplash.com/photo-1510414842594-a61c69b5ae57?ixlib=rb-4.0.3\\u0026amp;auto=format\\u0026amp;fit=crop\\u0026amp;w=1920\\u0026amp;q=80\",\"dimRatio\":60,\"overlayColor\":\"black\",\"minHeight\":500,\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:500px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-backward-gradient has-background-dim-60 has-background-dim\"></span><img class=\"wp-block-cover__image-background\" alt=\"\" src=\"https://images.unsplash.com/photo-1510414842594-a61c69b5ae57?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=1920&amp;q=80\" data-object-fit=\"cover\" /><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"3.5rem\"}}} -->\n<h1 class=\"has-text-align-center\" style=\"font-size:3.5rem\">Tu guía definitiva de Dénia</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textAlign\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1.2rem\"}}} -->\n<p class=\"has-text-align-center\" style=\"font-size:1.2rem\">Descubre por qué la capital de la Marina Alta es el destino favorito para miles de familias cada verano.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer {\"height\":\"80px\"} -->\n<div style=\"height:80px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":2} -->\n<h2>¿Por qué alquilar en Dénia?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Dénia no es solo sol y playa (aunque sus 20 km de costa son impresionantes). Ciudad Creativa de la Gastronomía por la UNESCO, ofrece una mezcla única de historia, sabor mediterráneo y naturaleza gracias al Parque Natural del Montgó.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><li><strong>Gastronomía:</strong> Disfruta de la famosa Gamba Roja de Dénia.</li><li><strong>Clima:</strong> Más de 300 días de sol al año.</li><li><strong>Conectividad:</strong> Ferry directo a Formentera e Ibiza.</li></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\"} -->\n<figure class=\"wp-block-image size-large is-style-rounded\"><img src=\"https://images.unsplash.com/photo-1544450579-7a9bc3487007?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=1200&amp;q=80\" alt=\"Playa de Dénia\" /></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"secondary\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-secondary-background-color has-background\" style=\"padding-top:80px;padding-bottom:80px\"><!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"has-text-align-center\">Inmuebles Disponibles en Dénia</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textAlign\":\"center\"} -->\n<p class=\"has-text-align-center\">Reserva ahora tu estancia en las mejores villas y apartamentos de la zona.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:query {\"queryId\":10,\"query\":{\"perPage\":3,\"pages\":0,\"offset\":0,\"postType\":\"product\",\"taxQuery\":{\"poblacion\":[\"denia\"]},\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"\",\"inherit\":false},\"displayLayout\":{\"type\":\"flex\",\"columns\":3},\"align\":\"wide\"} -->\n<div class=\"wp-block-query alignwide\"><!-- wp:post-template -->\n<!-- wp:post-featured-image {\"isLink\":true} /-->\n<!-- wp:post-title {\"isLink\":true,\"textAlign\":\"center\"} /-->\n<!-- wp:woocommerce/product-price {\"textAlign\":\"center\"} /-->\n<!-- wp:woocommerce/product-button {\"textAlign\":\"center\"} /-->\n<!-- /wp:post-template --></div>\n<!-- /wp:query --></div>\n<!-- /wp:group -->\n','Guía Completa de Alquiler Vacacional en Dénia','','publish','closed','closed','','guia-denia-alquiler-vacacional','','','2026-01-23 15:01:23','2026-01-23 14:01:23','',0,'http://alquipressjaime.local/guia-denia-alquiler-vacacional/',0,'page','',0);
INSERT INTO `wp_posts` VALUES (3527,0,'2026-01-23 15:01:23','2026-01-23 14:01:23','\n<!-- wp:cover {\"url\":\"https://images.unsplash.com/photo-1506197603052-3cc9c3a201bd?ixlib=rb-4.0.3\\u0026amp;auto=format\\u0026amp;fit=crop\\u0026amp;w=1920\\u0026amp;q=80\",\"dimRatio\":60,\"overlayColor\":\"black\",\"minHeight\":500,\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:500px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-backward-gradient has-background-dim-60 has-background-dim\"></span><img class=\"wp-block-cover__image-background\" alt=\"\" src=\"https://images.unsplash.com/photo-1506197603052-3cc9c3a201bd?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=1920&amp;q=80\" data-object-fit=\"cover\" /><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"3.5rem\"}}} -->\n<h1 class=\"has-text-align-center\" style=\"font-size:3.5rem\">Jávea: Un paraíso entre acantilados</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textAlign\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1.2rem\"}}} -->\n<p class=\"has-text-align-center\" style=\"font-size:1.2rem\">De la Playa del Arenal a la recóndita Cala Granadella. Descubre el paraíso turquesa.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer {\"height\":\"80px\"} -->\n<div style=\"height:80px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading -->\n<h2>Calas Imprescindibles</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Jávea es famosa por sus calas de grava y aguas cristalinas, ideales para el snorkel y el buceo.</p>\n<!-- /wp:paragraph -->\n<!-- wp:list -->\n<ul><li><strong>La Granadella:</strong> Elegida varias veces la mejor playa de España.</li><li><strong>Cala Barraca (Portitxol):</strong> Famosa por sus casitas de pescadores con puertas azules.</li><li><strong>El Arenal:</strong> La única playa de arena de Jávea, perfecta para familias.</li></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\"} -->\n<figure class=\"wp-block-image size-large is-style-rounded\"><img src=\"https://images.unsplash.com/photo-1563911302283-d2bc129e7100?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=1200&amp;q=80\" alt=\"Jávea Blue Window\" /></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"secondary\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-secondary-background-color has-background\" style=\"padding-top:80px;padding-bottom:80px\"><!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"has-text-align-center\">Villas de Ensueño en Jávea</h2>\n<!-- /wp:heading -->\n\n<!-- wp:query {\"queryId\":11,\"query\":{\"perPage\":3,\"pages\":0,\"offset\":0,\"postType\":\"product\",\"taxQuery\":{\"poblacion\":[\"javea-xabia\"]},\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"\",\"inherit\":false},\"displayLayout\":{\"type\":\"flex\",\"columns\":3},\"align\":\"wide\"} -->\n<div class=\"wp-block-query alignwide\"><!-- wp:post-template -->\n<!-- wp:post-featured-image {\"isLink\":true} /-->\n<!-- wp:post-title {\"isLink\":true,\"textAlign\":\"center\"} /-->\n<!-- wp:woocommerce/product-price {\"textAlign\":\"center\"} /-->\n<!-- wp:woocommerce/product-button {\"textAlign\":\"center\"} /-->\n<!-- /wp:post-template --></div>\n<!-- /wp:query --></div>\n<!-- /wp:group -->\n','Jávea (Xàbia): Las mejores calas para tus vacaciones','','publish','closed','closed','','mejores-calas-javea','','','2026-01-23 15:01:23','2026-01-23 14:01:23','',0,'http://alquipressjaime.local/mejores-calas-javea/',0,'page','',0);
